#include "exercise.h"
#include <assert.h>
#include <string.h>
#include <stdlib.h>
#include <math.h>
#include <stdio.h>
static bool positive(int x){return x>0;}
static bool bstring(const void*p){return (*(const char*const*)p)[0]==98;}
static void string_length(const void*p,void*out){*(size_t*)out=strlen(*(const char*const*)p);}
int main(void){
const char*g[]={"abc","def","ghi"};coordinate a,b;assert(find_word(g,3,"aei",&a,&b)&&a.row==1&&b.row==3&&b.column==3);assert(find_word(g,3,"cba",&a,&b)&&a.column==3&&b.column==1);assert(find_word(g,3,"gda",&a,&b)&&a.row==3&&b.row==1);assert(!find_word(g,3,"zzz",&a,&b));

return 0;}
